GimCorpus.put(450,0,[[1,5,"ומפני שתוכן נראה כברן. א\"א אין זה הטעם על דרך ההלכה אלא מפני שתוכן נראה כברן עשו גבו כתוכו ומטמא מגבו וא\"ת יטמא מאוירו ככלי חרס א\"כ יהיה חמור מכל הכלים הכתובים בתורה שלא מצינו שלש טומאות הללו בשום כלי מיעטו את האויר מפני שהוא חידוש:",1,0],[2,3,"ותוקעין בו הסדן. א\"א לשון המשנה תחתית הצורפים טמאה ושל נפחים טהורה:",1,0],[2,3,"ואם היתה של צורפים. א\"א תוספתא מפני מה תחתית של צורפים ושל זהבים טמאה מפני שמכניס לתוכה גרוטאות ושל נפחים טהורה ואם התקינה להכניס לתוכה גרוטאות טמאה:",2,0],[2,5,"שפופרת שחתכה. א\"א קשיא לי מה ששנינו בכלים פט\"ז בית הנגר בית המנעול בית המזוזה הרי אלו טהורין ואולי כשאין להם קיבול קאמר אבל שפופרת יש לה בית קיבול ובכלי קיבול לא חילקו זה החילוק האמור באותה משנה וכן כתבתי בפירוש תורת כהנים:",1,0],[2,8,"שאין עליו צורת כלי. א\"א תוספתא צרור המרגלית בזמן שתוכו טמא פשוטו טהור מיטמא ומיטהר אפילו י' פעמים ביום נראה מן הענין הטעם מפני שהוא מקפיד על צרור המרגלית שלא תתפשט כדי שתהא מזומנת להחזירה לתוכה והרי היא ככיס אבל אינו מקפיד על צרור המעות לפיכך אינו ככיס אפילו בזמן שהמעות בתוכו:",1,0],[3,1,"כל כלי עץ העשוי לנחת אפי' כו'. א\"א דבר זה איני יודע מאין הוציאו אלא משלחן של מקדש וממנורה שהקשו עליהם כלי עץ שעשוי לנחת הוא ואע\"פ שאינן מקבלין ארבעים סאה בלח ואינו מחוור דהתם איסורא נמי איכא בטלטולם ומה שאמר כל כלי עץ שהוא עשוי לטלטל מלא וריקם אפילו מחזיק מאה כור מיטמא למדה מספינת הירדן ואולי לא כמו שהוא סובר אלא מפני שספינת הירדן אין דרכה להורידה למים אלא טעונה אבל שאר כלים אע\"פ שפעמים מיטלטלין במלואן כיון שאין דרכן בכך אינן מטמאין וכן הוא במשנת כלים פט\"ו רבי יהודה אומר דרדור עגלה וקיסטות מלכים ועריבת העבדן ובור ספינה קטנה והארון אע\"פ שמקבלין ארבעים סאה טמאין שאין עשויים להטלטל אלא במה שבתוכו ושאר כל הכלים המקבלין טהורין שאין מקבלין טמאין אין בין דר\"מ לרבי יהודה אלא עריבת בעל הבית המקבלת לרבי יהודה טהורה אע\"פ שפעמים שמוליכין אותה מלאה לפורני ראה מה הלשון אומרת שאינן עשויין להטלטל אלא במלואן אבל פעמים כן ופעמים כן טהורין ואין הולכין בהן אחר חזקה:",1,0],[3,3,"ושאר כלי זכוכית. א\"א אמת כך מצא בתוספתא ולא ידעתי טעמה ואולי מפני שמלאכתן עבה והן עשויים לנחת אבל שאר כלים מלאכתן דקה ועשויין להטלטל במלואן:",1,0],[3,5,"היה בתוך הכלי תיבה קטנה. א\"א מעולם לא שמענו מוכני פירוש תיבה אלא גלגל ואופן שהוא מתגלגל עליו כמו ששנינו אף הוא עשה מוכני לכיור כדי שלא יהיו מימיו נפסלין בלינה ול\"נ שזה הגלגל אינו אלא למעלה או על שפתו שמעלין התבואה לשדה באותו גלגל לפי שיש טורח גדול במלואו או בהריקו ומשתמשים בהן דרך הגלגל ואילו היה הגלגל להתגלגל עליו שתי קושיות בדבר האחת שהרי אינם עשויים להטלטל כלל ומה צורך למוכני ואם כן עשויים הם להטלטל ועוד מה בין מוכני לעובי הרגלים שאין נמדדין עמה ואף על פי שהרגלים אינם נשמטים אלא ודאי כמו שפירשתי ונמדד עמה מפני שכל תשמישה על ידי המוכני:",1,0],[4,1,"והקלב שבונין עליו תיק הספר. א\"א לא ידעתי מהו זה ואינו במשנה נמנה עם כל אלה אבל מנו אותו בתורת כהנים עם הסולם והנחותא והוא כעין סולם הכתפי עושין למשאותם והקלב בלשון המשנה והאימום:",1,0],[4,1,"מפני שהם משמשי הכלים. א\"א יש מאלו הרבה שטהרתן מפני שהכלים עצמן משמשין עם הקרקע לפיכך התיקון שלהם וכיסוייהם טהורין אלא שרצה התנא לחבר הטהורין:",2,0],[4,2,"מפני שהוא ממשמשי הכלים. א\"א לישנא דתוספתא מפני שאינו עושה מלאכה בגופו כלומר סומך את הבגדים שלא יפלו לארץ:",1,0],[4,3,"מכבש של שכף פי' אושכף. א\"א זו המימרא מצאתיה בתוס' כלים לטהר וגם מצאתיה בתוספתא כלים בענין אחר מכבש של שכף בזמן שהוא קבוע חיבור אחד לטומאה ולהזאה נוטל ונותן אינו חיבור לא לטומאה ולא לטהרה ואפשר שיהיו במכבש של אשכפים שני עניינים:",1,0],[4,4,"וכן כלי עץ או עצם כו'. א\"א לא ידעתי מהו ולא מצאתי לזה שורש ואדרבה ראוי להיות בהיפך אם לא היה לכלי בית קבול וצפהו במתכת מקבל טומאה ע\"י צפויין וכן מצינו במקצת מקומות שהכלי בטל לגבי ציפוי:",1,0],[5,1,"והערק משיעשה בו צפירה. א\"א פי' בערוך נפה והטעם מפני שאדם משתמש באלו במה שהן משא\"כ בשאר כלים שהזכיר למעלה עכ\"ל:",1,0],[5,1,"ואין גולמיהן מקבלין טומאה. א\"א זאת הקורבה לא ידעתי מאין באה לו שהרי פירשו בו טעם מפני שמחוסרין שליקה וממרים את מה שבהם פירוש עושין מה שבהם מר ואין זה הענין בכלי עצם ואי ס\"ל כר\"נ דאמר במסכת חולין גולמי כלי עצם כגולמי כלי מתכות דמי לימא הכי ולמה ליה לדמויינהו לאשכרוע שהוא כלי עץ ומוציא מדין כלי עץ שאפילו שליקתו מעכבתו מפני שפוגם מה שנותנין בו:",2,0],[5,1,"ארובות של נחתומין וכו'. א\"א דבר זה בהיפך ארובות כמו ערוכות והוא הקטוף סרוד הוא שמוליך עליו המקרצות לתנור והטעם של נחתומין טמא מפני שהוא מייחד כלי לזה התשמיש אבל של בעל הבית אין תשמישו תדיר ואין מייחדו לכלי ואם ייחדו טמא והכי איתא בתוספתא:",3,0],[5,1,"והלוח שעורכין עליו וכו'. א\"א זה שיבוש:",4,0],[5,1,"כלי עץ כו'. א\"א בערוך פירש נפה של שיער וכן משמעותו בכ\"מ אלא שזה הפרק כולו אינו מדבר באורג אבל נראה כי הוא של עור כמו אותן של רופאים ובו דברה המשנה תחלה וממה שאמר רבי יהודה בסמוך אף של גדלת טמא מושב שהבנות יושבות בתוכו וגודלות למדנו שלא דבר ע\"כ בשל שיער אלא בשל עור כאשר כתבתיה:",5,0],[5,3,"והנקטימון. א\"א קשיא לי מה ששנו במסכת שבת אנקטמין טהורין ואין יוצאין בהן בשבת:",1,0],[5,5,"קוצין שאורגין. א\"א לשון המשנה פטיליא טמאה וחסינה טהורה והטעם מפני שאינה עשויה לטלטל כלל:",1,0],[5,6,"עלין שמסרגין. א\"א זהו סגניות שבמשנה:",1,0],[5,10,"האקון. א\"א פי' בערוך כלי של מצודת דגים:",1,0],[6,2,"ויהיו בכלי ג' רמונים. א\"א אין מדבריו אור לחשכים ולשון המשנה הרמונים שאמרו ג' אחוזין זה בזה ונראין לי פי' שיעור מוציא רמון ליטהר אפילו בכלי שמחזיק ברחבו ג' רמונים זה בצד זה אע\"פ שרובו קיים שלא נפחת אלא שיעור הא' טהור וכ\"ש אם לא היה מחזיק אלא שנים שהרי נקיבתו מחצה פי' אחר הרמונים שמשערים בהם לא במין הגדולים והגסים שיוצאין אחד אחד ביחור שלהם אלא באותו מין שיוצאין ג' בעוקץ אחד והם ממין הבינוני ובאותן הג' עצמן אין משערין לא בגדול שבהם ולא בקטן שבהם אלא בבינוני ומסעד לזה הפירוש מה שאמרו באותו הפרק ר\"י בן נורי אומר לא הוזכרו רמוני בדן אלא לשער בהן את הכלים למדנו שיש להם ענין באי זה משערין וזה עיקר עוד יש לפרש כשהן ג' אחוזין זה בזה והכי יוצאין מצדן אין בנקב אלא שיעור מוציא רמון אחד והא דבעינן שלשה אחוזין זה בזה כדי שהכובד מוציא ואילו היה אחד לא היה יוצא אע\"פ כן טהור הכלי וכ\"ש אם היה יחיד ויוצא וקצת ראיה לזה הפירוש דברי רשב\"ג שהם בסמוך והם בזה הענין ואולי זהו פירוש זה המחבר:",1,0],[6,3,"והפחלץ של גמלים. א\"א זאת לא מצאתי וקשיא לי הא דתנן פכ\"ד הפחלץ של גמלים טהורים מכלום ועוד תניא פרק כלי עור הסל והפחלץ של גמלים שעשאן מתחילה מקבל רמונים טמאים הא למדת דאם אינם מקבלים טהורים:",1,0],[8,2,"הרי אלו מקבלין טומאה לפי שאינן גולמין. א\"א חסרון דעת אני רואה בכאן שלֹא נאמרו דברים הללו לענין גולמים ולא לקבל טומאה מכאן ולהבא אלא לפי שכלי מתכות חוזרין לטומאתן הישנה לפיכך כלי שנעשה משברי הכלים ומן המתכות שהיו ראויים לקבל טומאה אע\"פ שנשחתו ממלאכתן כיון שהחזירן לכלים מיד טמאים לאוכלי טהרות שמא טמאין היו וחזרו לטומאתן:",1,0],[9,1,"כיצד עקרב של פרומביא. א\"א נ\"ל שלא מן השם הוא זה אלא שהעקרב הוא ממשמשי ידי האדם בבהמה משא\"כ בלחיים ומה שאמרו בתחלת הפרק כל כלי מתכות שיש להן שם בפ\"ע טמא חוץ מן הדלת וכו' לא בא למעט אלא כיסויי הכלים וחפויים כמו שמפורש במקומו:",1,0],[9,3,"ואין לכל גרגיר ממנו. א\"א כל מ\"ש משום שיש לו שם בפ\"ע או משום שאין לו שם בפ\"ע אני איני תולה אותם בשם אלא הטהורים מפני שאינם משמשים בפני עצמם כלום אלא על ידי חבורם עם השאר והטמאים מפני שמשמשים בפני עצמם:",1,0],[9,8,"קנה מאזנים של עץ. א\"א נ\"ל אפילו של מתכת צריך לאונקלאות לפי שאינו עושה מלאכה כי אם עמהם וראיה לדבר שכל אותו הפרק בכלי מתכות ובפי\"ז תנן קני מאזנים והמחוק שיש בהם בית קיבול מתכת טמאים וכאן מדבר בשל עץ:",1,0],[9,8,"מפני האונקיאות התלויות בו. א\"א דבר מזוייף הוא זה בעיני שהרי לא הזכירו במשנה לבעלי בתים קבע ולשון התוספתא קנה מאזנים של סרוקות אם יש בו אונקיאות טהור אין בו אונקלאות ואין בו אונקיות טמא פירוש אונקלאותיו טהורין ולשון המשנה המדוייק ושל בעלי בתים אם יש בו אונקלאות טמא וכן פירוש המשנה קנה מאזנים של סרוקות שהן שוקלים משקלים קטנים ויש באותו הקנה חריצים דקים בצד הא' ותולין בו אוקיא אחת של מתכת בחוט א' ובאותו אוקיא שוקלין כמה אונקייאות לפי הרחקה והוא הנקרא בלשון ישמעאל קלסטין והוא אינו צריך לאונקליות אבל יכול לשקול כמה אוקיות באותה אונקייא התלויות בה או באונקלי אם יש בה אבל של בעלי בתים שהם שוקלים משקלים גדולים אותה האוקיא התלוייה בחוט אינה כלום וצריך שיעשה בראשי הקנה כעין אונקלאות שקורין גופו\"נש ראשיהם כפופים נותנין המשקולות באונקלא האחת והקמח באחרת ע\"כ אמרו אם יש בו אונקלאות טמא מפני שראוי למלאכתו ואם לא טהור וזהו באור המשנה:",2,0],[10,1,"טהור עד שיצרפנו. א\"א פירושו לפי שהמסמר שנוקבין בו את החבית צריך שיהיה חזק הרבה משאר מסמרות הילכך בהתקנה לבדה אינה מטמאה עד שיצרפנו באש ובמים:",1,0],[10,3,"מסמר הגרע. א\"א לא נראה כן מן התוספתא שהרי א\"ר ישמעאל בן יהודה משום ר\"ש מסמר הגרע טהור שלא נעשה אלא לשמש עם הקרקע אבל נראה שתוקעין אותו בקרקע ותולין בו הכלי שמקבל דם הקזה ויש אומרים מסמר ארוך הוא שהמוקז סומך בו את זרועו בשעת הקזה:",1,0],[10,9,"טסין של מתכת. א\"א מתניתין פי\"ב היתוכים טמאים והפרכים טהורים תוספתא אלו הם היתוכים אלו שהחנווני מנער בהן את הקדרה אלו הן פרכים הקבועים בקירות פירש בעל הערוך מלקחיים שתופס בהם את הקדרה ומערה לתוך הקערות פרכים אותו מלקחיים שתופסין בהם אורגי היריעות הקנים או השתי והוא ורדו\"ר בלעז ואם עומדים קבועים לנירים ולקירוס קורא אותם פרכים של שם שכובשים הקנים והארוג מלשון בפרך כך נ\"ל והם כמו טבעת כלים:",1,0],[10,15,"ואם יכולין הכל לפרקה ולהחזירה. א\"א זאת הפסקא של חצוצרת לא מצאתי כדבריו וכן היא שנוי' אצלנו בב' ספרים חצוצרת של פרקים הרי זו טמאה נתפרקה העליון טמא והתחתון טהור ומה שאמר שאם אין יכול להחזירה אלא אומן מקבלת טומאה כשהיא מחוברת אבל אם הדיוט יכול להחזירה אינה מקבלת טומאה אפילו מחוברת דבר זה רחוק מאד ובהפך נמצא במשנה פכ\"ו סנדל עמקי וכיס של שנצות הרי אלו מטמאין ומטהרין שלא באומן אמר רבי יוסי לא כל הכלים (ס\"א והלא כל הכלים) מתטמאין ומתטהרין שלא באומן אבל אלו אע\"פ שמותרין טמאין שההדיוט יכול להחזירם וכן בגמרא דשבת לגבי ענבל וזוג אמרינן הואיל והדיוט יכול להחזירם אפילו נטלו ענבליהם טומאתם עליהם אלמא כיון שיכול הדיוט להחזירו כל שכן שהוא כמחובר ואפילו נתפרק וכל שכן בשעת חיבורו:",1,0],[11,7,"והרונקי בפני עצמה. א\"א פי' בערוך ברזל של רהיטני ואני תמה על ברזל של רהיטני מעצד א\"כ למה לא יטהר בפני עצמו ועוד מצאתי בתוספתא כלים פ' הנידון האיזמל של רונקי טמא בפ\"ע למדנו שהרונקי האמור במשנה שהוא טהור על העץ נאמר ולא על הברזל ואולי ג\"כ נאמר על המעצד:",1,0],[11,19,"כלי שיש בראשו. א\"א זה כתב תחת זולמטרא ומעולם לא עלה על דעת שירימו בו דשן בראשו אחד ובראשו שני יצלו בשר אבל הוא כלי שיש בו בית קיבול מצד אחד לקחת התבשיל מן הקדירה לתת בקערה והמזלג שבראשו השני לוקח חתיכות משם מן הבשר ולתת לקערה קולייר\"א בלע\"ז והמלה עצמה לעז הוא:",1,0],[11,20,"כלי שבראשו כף אחד. א\"א זה עשה תחת קליגריפין ובערוך לא פירש כן אלא בראשו אחד כעין פאל\"א להדביק בו פת בתנור ולרדותו והשני לגרוף בו את האפר והגחלים אבל נראה כדבריו שזה הוא קליגריפין:",1,0],[11,24,"לא נטמאה וקבעה. א\"א טעה בכאן טעות גדולה שלא הלכה המשנה ולא התוספתא על זה הדרך שאם עשאה מתחלתה לתחת הדלת טהורה אע\"פ שמשתמש בה אבל אם היתה כלי וחברה לו טמאה עד שיחבר פירוש במסמר ומאי אם היתה כלי שלא עשאה לדלת אלא לכלי וזו היא מה שראה בתוספתא אבל אם היתה טמאה וחברה טמאה כלומר שעשאה לדבר הראוי לקבל טומאה דהיינו לשם כלי והוא טעה בלשון התוספתא ולא נזהר מלשון המשנה גם דבריו מעורבבים ומבולבלים וסותרין זה את זה:",1,0],[12,3,"ויטביל כשהוא כלי. א\"א אני לא הכרתי דבריו לא מן המשנה ולא מן התוספתא ומה שאמר רבי יהושע בתחלה במשנה אין מטהרין אלא שלמים זה הוא שאמר בסוף אין הזאה פחות משלישי ושביעי כלומר דהיינו כעין שלמין שאין שבירתן עולה להם במקום מים כמו שאמר רבי אליעזר ולעולם אם היזה עליהם בשלישי ונשברו והתיכן בו ביום מזה עליהן פעם שנייה בשביעי וטהורים שהרי מטהרין ג' וז' כשהם שלמים וכך נ\"ל והמחמיר יותר מזה עליו הראיה:",1,0],[12,13,"נפגם בו שליש. א\"א דעת כריסו היא זאת לשון המשנה נפגם שלש ברובו טהור ויש שקורין כרובו וענין אחד הוא ותחלת המשנה כוס שנפגם רובו טהור נפגם בו שלש ברובו טהור ופירושו נפגם רובו שנטלה ממנו חתיכה אחת גדולה שהיא רוב הקיפו או אפילו שלש פגימות שהן מפוזרות ברובו טהור שהן נחשבות רוב שבו:",1,0],[13,4,"כלי חרס שנגעו. א\"א כבר כתבתי במקום אחר מה שנראה לנו על זה:",1,0],[13,5,"שנאמר אל תוכו לרבות את האוהלים. א\"א הלכתא כוותיה ולא מטעמיה דכלי שכפהו על הטומאה כלי הוא ותוכו של כלים נקרא אהל אבל האהלים שהוצרכו לרבות הם השידה התיבה והמגדל הבאים במדה שהם כאהלים שאינן צריכין צמיד פתיל באהל המת שאפילו בכיסוי בעלמא הם מצילין באהל ואפילו הכי לענין אויר כלי חרס מיטמאין בכלים ולא נחשוב אוירם כאויר בית אע\"פ שהוא כבית לענין הצלה ומרבה אותם בספרא מכל כלי חרס ולא מאל תוכו כאשר כתב:",1,0],[13,7,"וכן אם נמצאת. א\"א זה כתב מפני שראה במשנה ואם היה באויר אפילו היה שם כזית מן המת טהור וסבור שעל השרץ אמר שהיה באויר ולא כן דמה שלא אמר אלא על התנור אם היה עומד באויר שלא תחת תקרה אפילו היה שם כזית מן המת טהור התנור:",1,0],[13,12,"היה השרץ בתחתונה וכו' עד וחוזר ומטמא את האילפס. א\"א אני כתבתי עודפות אך לא מצאתי בנוסחאות אלא עודפת ואולי שהוא דוקא וכך פירושה שהעליונה עודפת על האמצעית והתחתונה עודפת על כולם והשרץ בעליונה נמצא השרץ לאמצעיות תוך תוכו או אפילו נאמר שהעליונה שוה לאמצעיות והתחתונה עודפת מה שבאמצעיות טהור מפני שהשרץ שבעליונה תוך תוכו הוא להם אבל התחתונה ודאי טמאה וסוף דבר אין זה כלום שא\"כ הכל טמא מאויר התחתונה שהיא עודפת על כולה אלא העיקר ששתיהן שוות ועודפות על האמצעיות כולן טהורות וחוץ מן העליונה שהשרץ בתוכה ואם יש עליהן משקה טופח כולן טמאות שהעליונה מטמאה את המשקה שעל גבה והמשקה מטמא את האלפס שבצדו ואותו האלפס חוזר ומטמא המשקה שעל גבו וכן כולן אפי' מאה ומכאן יש סיוע למה שכתבתי שהמשקה מטמא כלי חרס מגבו:",1,0],[13,12,"ואין שפת התחתונה עודפת. וחוזר ומטמא את הלחם אבל אם השרץ בעליונ' והתחתונ' עודפת כל שיש בה משקה טופח טמא שהמשקה מטמא:",2,0],[13,14,"בתיו קבועין. א\"א והוא שיש שם דופן עודף:",1,0],[14,6,"שסוף משקה לצאת. א\"א יש בכאן שיבוש וכן שנינו בתוספתא פתילה מליאה משקין טמאין מבפנים ונגבו מבחוץ ונפלו לאויר התנור בשעת היסקו טמא שלא בשעת היסקו טהור אבל ספוג בין כך ובין כך טמא מפני שהוא עשוי למיכנס ובמשנה ספוג שבלע משקין טמאין ונגוב מבחוץ ונפלו לתנור טמא שסוף משקה לצאת וכן חתיכה של לפתות ושל גמי ר\"ש מטהר בשני אלו אלמא שאני ספוג משאר בולעים מפני שהוא כלי שמצניעין בו משקין ולדעת תנא קמא אף בלפת כמוש וגמי עושים כן שמניחין אותם על גבי מכה להיות מוצץ בו את הלחם ובודקין בהן את היין והם כמו כלים והכי איתא בתוספתא:",1,0],[14,9,"אם היה בכלי שטף. א\"א זה ההפרש לא נמצא בשום מקום לענין צמיד פתיל וההפרש שביניהן לענין קבולי טומאה הוא דבכלי חרס אזלינן למה שהוא מיוחד ובכלי עץ במוציא רימון מפני שהוא ראוי לתקנו ואין אדם פורש ממנו עד שינקב במוציא רמון ולפיכך שנו במשנה כל כלי בעלי בתים שיעורן ברמונים בכלל לזה השיעור כולן שוים אבל יש שיעורים אחרים שאינן כל הכלים שוים שיש לכלי חרס שיעורים קטנים יותר מזה אבל לענין הצלה מאויר הטומאה כולן שוים כלומר למה שהוא מיוחד אזלינן ומשנה שלימה היא פ\"ח עיין ותמצא:",1,0],[14,10,"סתם נקב כלי חרס בזפת. א\"א טעה בכל זה שאינו אלא בסתמו בטיט אבל אם סתמו בזפת התנור טהור מפני שהזפת חיבור לה וכסתום דמי ופיה למעלה והוי תוך תוכו אבל שאר הכלים אין הזפת חיבור להם והתנור טמא דכנקובים דמי וכ\"ש אם סתמן בטיט שאינו חיבור והכי איתא בתוספתא:",1,0],[15,5,"אפילו במשקין נטמא הכל. א\"א אני לא מצאתי בתוספתא כדבריו וכך היא שנויה תנור חצצו לשנים והוסק אחד מחלקיו ונטמא במשקין הוא טמא וחבירו טהור בשרץ הכל טמא והעובי שביניהם כולן טמאין קשה לי בזה אם הכל טמא אף על החלק השני קאמר מה צורך לומר על העובי שביניהם שהוא טמא לפיכך קרוב אני לומר שהעובי שביניהם טמא פירוש הוא למה שאמר הכל טמא הוסקו שניהם ונטמא אחד מהם א\"ר יוסי משום ר\"י בן נורי חולקין את עוביו המשמש לטמא טמא ולטהור טהור בד\"א שחצצו ואח\"כ הסיקו אבל הסיקו ואח\"כ חצצו מטמא במגע ובאויר נטמא אחד מהן במשקין הרי חיבור טהור כך מצאתי בתוספתא בשתי נוסחאות שלא כדבריו ולא נתבררה אצלי כהוגן:",1,0],[17,6,"אבל אם נטמאת אחת מהן מאוירה בלבד. א\"א לי נראה מה שאמר אינו מטמא באויר אינו מיטמא החצר כשהשרץ באויר הכירה למעלה מכנגד אויר החצר אבל בכנגד אויר החצר אפילו פחותה מכאן טמא זה מאוירו של זה וזהו שאמרו וכנגדו מטמא באויר:",1,0],[18,1,"בשולי המחץ הואיל ונעשית. א\"א כלל כלל לא נתקבל בעיני זה הפירוש שהחבית תיעשה בית יד למחץ ונראה בעיני חבית של שייטין חדה וארוכה:",1,0],[18,2,"וכן מגופת היוצרים. א\"א זה כתב תחת מה שראה במשנה מגופת היוצרין שהוא פותח בה טהורה ושהוא גומר בה טמאה ונדמה לו פותח בה חוקק בה ולא נגמרה מלאכתה ולא כן ידמה לי אלא שהוא נוקב בה כלל בשעת עשייתה מניח בה הנקב ושהוא גומר בה שאינו מניח בה נקב:",1,0],[18,6,"מוציא פרוטות מתטמא. א\"א אני שונה רבי יוסי מטמא מפני שהוא מוציא פרוטות והוא אמר אע\"פ שמוציא פרוטות ובעל הערוך פירש כלי שיש בו נקבים קטנים אחד מלמעלה ואחד מלמטה העליון רחב מעט מן התחתון וכשנותן אצבעו על העליון אינו יוצא כלום מן התחתון ורבי אלעזר ברבי צדוק מטהר מפני שהוא מנוקב ורבי יוסי מטמא מפני שאותו הנקב מוציא פרוטות ושיעור כלי חרס ליטהר אינו במוציא פרוטות ודלא כר\"א שיש לדעתו שהוא כלי טהור במוציא פרוטה קטנה זה הפירוש לדעת המאסף ואינו מקובל דהוה ליה למיתני אע\"פ שמוציא פרוטות ומסתברא כפירושא דגאון ופרוטות כמו הפורטים על פי הנבל והוא מלשון פרט כרמך כלומר הוצאות דקות פעם מוציא ופעם אינו מוציא כשסוגר מלמעלה אינו מוציא מלמטה הילכך אינו כלי נקוב שאינו עשוי אלא להנאה:",1,0],[18,10,"לא בא לרבות אלא שברי כלי חרס. א\"א כמה אני תמה על זה כי כל המשניות והתוספתות מלאות מזה שהכלי הנשבר ועושה מעין מלאכה ראשונה ובכלי עץ שיהיה לו בית קיבול טמאים וכשרבה הכתוב שברי כלי חרס רבותא שהייתי סבור חרס הנשבר אין לו תקנה:",1,0],[18,16,"חזקת חרסים. א\"א מצאתי נוסחא זו מוחלפת במקצת הספרים הנמצאים בכל מקום טמאין חוץ וכו' מפני שרובן מן הגסטראות וחיי ראשי זו הנוסחא מיושרת בעיני יותר מן האחרת כלומר חזקתן שנשברו עד שלא באו להיות כלי והיוצר הסיקן עם שאר הכלים שלא לצורך ואינן נחשבות בעצמן להיותן כלי שהחשיבות מחשב השברים והמשנה שאמרה גסטרא שנמצאת בכבשן משנגמרה מלאכתה טמאה התם מפני שנמצאת עם כלים שלמים אומר שמא כלי שלם היה ונשבר משנגמר היסקו אבל בית היצירה אין שם אלא שברים וחתיכות ומעולם לא באו לכלל כלים וזהו עיקר והגירסא האחרת איני יודע לפרשה:",1,0],[19,11,"אפילו היתה כנגד החדוד לא נטמא. א\"א אני איני אומר כן אלא שאם נכנס שם שרץ לתוך הגסטרא כל החידודין טמאין עמו אבל אם נכנס שרץ לאויר לחדודין היוצאין אין הגסטרא מיטמאה מאותו אויר שאין אויר החידוד אויר הגסטרא הואיל ואינן מקבלין עמה זיתים:",1,0],[20,3,"ובגפסים אינן חיבור. א\"א מצאתי בשתי נוסחאות בהיפך מזה באלו חיבור ובשאר הדברים אינן חיבור:",1,0],[20,7,"מגופת חבית שטפל בטיט. א\"א טעה בהצעת המשנה וכך היא הצעתה יבלית שטופלין בה את הפטסין הנוגע בה טמא מגופת החבית אינה חיבור והנוגע בטפלת התנור חיבור הוא סבר מגופת החבית על הטפלה הוא חוזר ולא כן ידמה ולבבי לא כן יחשוב שהיה לו לומר שעל מגופת החבית אינו חיבור ולא היה צריך יותר ועוד פתח בפטסים וסיים בתנור ועוד מי ראה מעולם טפלה על גבי מגופה ומגופה עומדת ליטול וטפלה עשויה לקיימה אלא ודאי מילי מילי קתני אע\"פ שהיבלית חיבור לפיטס המגופה אינה חיבור לחבית ואע\"פ שזו אינה חיבור טפילת התנור אע\"פ שדומה לזו חיבור:",1,0],[21,1,"ושל חלוק שהוא קרוע. א\"א זה עשה תחת אפרקסותו ולא ידעתי לשונו והשמלה שנותן על ברכיו בשעה שמגלח וזו מעפורת שבמשנה:",1,0],[22,24,"שלשה על שלשה. א\"א לשון התוספתא שבכה שנקרעה ונתנה על הכסא וכו' ובשרו נוגע בכסא טהורה וכן העור והמפץ שנקרעו ונתנה על הכסא ומכאן הוציא שלשה על שלשה:",1,0],[22,27,"ומתטמא במדרס. א\"א אני אין לי אלא שאר טומאות אבל טומאת מדרס אין לו שהרי בטלו מתורת מדרס ואם עשאו כדור בפני עצמו אף משאר טומאות טהור מפני שהתפירה ממעטו והו\"ל כפחות משלשה שהתקינו לפקוק בו את המרחץ שבטלו מתורת בגד וטהור:",1,0],[23,3,"פחות משלש אצבעות טהור מכלום. א\"א זה כתב מדעתו שהרי אמרו ולאחיזה כל שהוא ואולי במקצע לכך ולפיכך אפילו כל שהוא מפני שהוא ככלי או כבגד קטן:",1,0],[24,6,"ואם חישב עליו להיות עור שלחן. א\"א כמדומה אני זו היא קטבליא:",1,0],[25,3,"עור המחופה על הברזל. א\"א נראה לי בשנטמא כשהוא מחובר קאמר ויש בו כשיעור אבל הברזל טהור מן המדרס שעליו אבל לא טהור משאר טומאות דאי לכתחילה קאמר ברזל טמא בשאר טומאות פשיטא ועור נמי אם יש בו כשיעור פשיטא ואי לית ביה כשיעור אמאי טמא מדרס:",1,0],[25,20,"ואוכף של נאקה. א\"א אוכף של נאקה דברי הכל טמא מושב עיין במשנה ולא חילקו אלא בטפיטן של סוס:",1,0],[26,7,"וסדק שלה. א\"א אין דרך התוספתא כן אלא שנסדקה ולא ניקבה במוציא זית עדיין טמאה טומאת מת ואם חישב עליה לישיבה טמאה אף מדרס כדעת רבי ואם ניקבה כמוציא רמון אף על פי שחישב עליה טהור מכלום עד שיעשה בה מעשה לישיבה דלא כרבי ודלא כר\"ע ואם היתה מחזקת יותר מתשעה קבין צריך שיקצע בה לישיבה ודלא כר\"ע והקיצוע הוא מעשה גדול להפנת ישיבה זו היא דרך התוספתא ושאר דבריו רוח:",1,0],[26,13,"מפני שראויין לסומכן. א\"א זה לדעת רבי נחמיה ודלא כרבנן עיין במשנה פי\"ח ועוד קשה דידיה אדידיה ולמעלה לא כתב כן:",1,0],[27,2,"שנסדקה טמאה. א\"א והוא שחשב עליה לישיבה כדעת רבי דפליג עליה דרבי יוסי בר\"י כדכתבינן לעיל:",1,0],[27,5,"לפי שאינו ממשמשי אדם. א\"א זה הטעם מצא חן בעיניו ותולה בו כל הדברים ובכאן אינו אלא מפני שאינו עשוי אלא כדי שלא יתלכלכו אצבעותיו בשמן העורות ודומה לו קסיה של צבעים ושל נפחים שהיא טהורה מפני שהוא לקבל את הזיעה ולא לקבלה אחרת:",1,0],[27,15,"ושעושין לשחק בה. א\"א לשון המשנה ושל יוצאת החוץ טהורה מכלום והם הזונות שמראות את שערן והנקבים גדולים מאד ואין עליהם תורת בגד שאינה ראויה אלא לזונות והרי היא כמי שנקרעה ואינה מקבלת רוב השער והכי איתא בתוספתא:",1,0],[27,17,"במוציא רמון שתיהן טהורות. א\"א ולא נתחוור אצלי זה הטעם למה שתיהן טהורות והלא תיקנה בשטלאה עליה ונראין דברי הרב היוני ז\"ל שפירש הולכין אחר הבריא שאם הוא טמא אף המהוהה טמא וכן כולן וכן דרך התוספתא ואי קשיא לך הא דתנן פי\"ח כרע שהיתה טמאה מדרס וחיברה למטה כולה טמאה מדרס הרי שנוסף מביא טומאה על העיקר וכאן אמרו שהולכין אחר העיקר לא דמי התם הכרע צורך המטה שאין תשמיש למטה בלא הכרע אבל הכא טלאי על גבי כלי ואחר עיקר הכלי הולכין בין שהניח הטלאי מבפנים או מבחוץ אבל שתיהן שוות הולכין אחר הפנימית:",1,0],[28,1,"הרי זה מנגבן והן וכו'. א\"א תוכן טהור ושאר אחוריים שאין היד מטמא מן האוגן ולא זה וזה מיהו לא ישתמש בו עד שינגב שמא יגע במשקה:",1,0],[28,2,"לא נטמא תוכן. א\"א ואף לא אחוריהן ומ\"ש אינו מחוור עיין בבכורות:",1,0],[28,3,"על מקצתן נטמאו כולן. א\"א הא דלא כהלכתא דר' יהודה היא דאמר הכי ור' מאיר ור\"ש פליגי עליה והוה ליה רבי יהודה יחיד אצל רבים:",1,0]]);
